   "id": "z3b5a34ec",
   "sez": "mondo",
   "titolo": "Mosca arresta un giornalista giapponese con l'accusa di spionaggio",
   "orig": "Russia arrests Japanese journalist on alleged espionage",
   "lead": "La Russia ha arrestato sull'isola di Sakhalin, nell'estremo oriente del Paese, un giornalista del quotidiano Hokkaido Shimbun, accusandolo di aver raccolto informazioni sulle capacità difensive russe per conto di Tokyo. L'arresto, confermato dal servizio di sicurezza FSB, arriva in un momento di tensioni crescenti tra Mosca e Tokyo. La portavoce del ministero degli Esteri russo Maria Zakharova ha commentato il caso, che si inserisce in una più ampia escalation diplomatica tra i due Paesi, legata anche all'allineamento del Giappone con le sanzioni occidentali contro la Russia per la guerra in Ucraina.",
   "more": [
    "L'FSB è il servizio di sicurezza federale russo, erede del KGB sovietico, che si occupa di controspionaggio e sicurezza interna. Sakhalin è un'isola russa nell'estremo oriente, vicina al Giappone, storicamente oggetto di contese territoriali tra i due Paesi."
   ],
