   "sez": "mondo",
   "titolo": "Gli alleati di Kyiv si riuniscono in Polonia dopo il sabotaggio Starlink e l'accordo Trump sul diesel russo",
   "orig": "Ukraine allies in Poland after Starlink sabotage, Trump diesel deal",
   "lead": "Rappresentanti degli alleati dell'Ucraina si sono incontrati in Polonia dopo un atto di sabotaggio contro infrastrutture Starlink e le polemiche suscitate dall'accordo tra Donald Trump e la Russia sul diesel. Il ministro degli Esteri tedesco Johann Wadephul ha detto che episodi ibridi come l'incendio doloso dimostrano che l'Europa è «nel mirino della Russia». Il ministro britannico Ed Miliband ha parlato di «giorni molto difficili» sul piano diplomatico causati dall'intesa di Trump sul petrolio russo.",
   "more": [
    "Starlink è il sistema di internet satellitare di SpaceX, usato anche in Ucraina per comunicazioni civili e militari durante il conflitto con la Russia; attacchi alle sue infrastrutture vengono letti come forme di guerra ibrida contro gli alleati occidentali di Kyiv."
   ],
