   "sez": "cultura",
   "titolo": "Girls di Lena Dunham torna per una serie limitata su HBO",
   "orig": "Lena Dunham's Girls to return for limited HBO run",
   "lead": "Dieci anni dopo la conclusione della serie originale, HBO ha annunciato il ritorno di «Girls», la serie creata da Lena Dunham, con una nuova stagione limitata. Il network ha spiegato che il progetto esplorerà il «traguardo dei quarant'anni» per le protagoniste, riportando sullo schermo i personaggi che avevano segnato la serie cult sulla vita di un gruppo di giovani donne a New York. Lo riferisce BBC News.",
   "more": [
    "«Girls» è stata una serie HBO ideata e interpretata da Lena Dunham, trasmessa dal 2012 al 2017, diventata un riferimento culturale per il racconto della vita di giovani donne tra incertezze professionali, sentimentali e identitarie."
   ],
