   "id": "z262a14ad",
   "sez": "economia",
   "titolo": "Moody's: la guerra in Iran costa in media 2.000 dollari a famiglia americana",
   "orig": "Moody's: 'La guerra in Iran costa a ogni famiglia Usa una media di 2.000 dollari'",
   "lead": "Secondo l'agenzia di rating Moody's, il conflitto in Iran sta avendo un impatto economico diretto sui consumatori statunitensi, con un costo medio stimato di 2.000 dollari per famiglia. A livello nazionale, l'agenzia calcola che gli oneri complessivi per i consumatori americani legati alla guerra ammontino a 265 miliardi di dollari. La stima evidenzia come le tensioni in Medio Oriente si riflettano sui prezzi e sui costi sostenuti dalle famiglie negli Stati Uniti. Lo riferisce ANSA.",
   "more": [
    "Moody's è una delle principali agenzie internazionali di rating finanziario, che valuta il merito di credito di Stati e aziende; le sue stime sui costi economici dei conflitti vengono spesso usate per misurare l'impatto delle crisi internazionali sui mercati e sui consumatori."
   ],
