   "titolo": "Un turista americano finisce senza soldi in Giappone e viene arrestato per overstay del visto",
   "orig": "American man runs out of money in Japan, gets arrested for overstaying tourist visa",
   "lead": "Un uomo americano di 36 anni si è presentato sabato sera alla stazione di polizia della città di Izumi, nella prefettura di Kagoshima, chiedendo aiuto perché rimasto senza soldi in Giappone. L'uomo ha detto di voler tornare a casa, ma le autorità lo stanno trattenendo per il momento, poiché il suo soggiorno ha superato la durata consentita dal visto turistico, configurando una violazione delle norme sull'immigrazione. Lo riferisce SoraNews24.",
   "more": [
    "Il visto turistico in Giappone consente soggiorni di durata limitata senza necessità di permesso di lavoro; il superamento di tale periodo («overstay») costituisce un reato amministrativo che può comportare il fermo da parte delle autorità e provvedimenti di espulsione."
   ],
