   "lead": "Engineering News-Record ha assegnato un Award of Merit nella categoria aeroporti/trasporti alla Silver Line Equipment Maintenance Facility, la quarta struttura regionale ferroviaria realizzata da Dallas Area Rapid Transit. L'impianto sosterrà la flotta di treni diesel multipli di ultima generazione della Silver Line, che qui verranno puliti, sottoposti a manutenzione e riforniti di carburante. Lo riferisce Engineering News-Record.",
