    "Dallas Area Rapid Transit (DART) è l'agenzia di trasporto pubblico dell'area metropolitana di Dallas, che gestisce linee di autobus e treni leggeri; le unità diesel multiple sono treni passeggeri autopropulsi usati su linee non elettrificate."
