   "lead": "David Kogan, presidente dell'Independent Football Regulator (IFR), l'organismo che rilascia le licenze ai club di calcio inglesi, ha dichiarato che si dimetterebbe se subisse pressioni politiche riguardo alla gestione dello scandalo sui pagamenti del Manchester City. Kogan ha precisato di non aver finora subito «assolutamente nessuna pressione politica» e ha espresso l'auspicio di raggiungere un accordo sulla redistribuzione dei fondi tra le leghe calcistiche inglesi.",
