   "titolo": "Scoperti 11.700 nuovi virus nel più grande giacimento di metalli del fondale oceanico",
   "orig": "Chinese team finds 11,700 new viruses in world’s biggest seabed metal deposit",
   "lead": "Un team di ricercatori cinesi ha individuato 11.700 nuovi virus nella zona di Clarion-Clipperton, nell'Oceano Pacifico tra Messico e Hawaii, dove a profondità fino a 6.000 metri si trovano miliardi di noduli metallici a forma di patata. L'area custodisce riserve di nichel, cobalto e manganese che secondo alcune stime potrebbero superare quelle note sulla terraferma. Finora nessuna attività mineraria commerciale è stata avviata, ma l'International Seabed Authority ha già concesso 17 licenze di esplorazione. Lo riferisce South China Morning Post.",
   "more": [
    "La zona di Clarion-Clipperton è un'estesa pianura abissale del Pacifico ricca di noduli polimetallici, oggetto di crescente interesse internazionale per l'estrazione di metalli strategici usati nelle batterie, ma anche al centro del dibattito scientifico sui rischi per ecosistemi marini poco conosciuti."
   ],
