   "lead": "Nel quartiere romano di Centocelle sono stati intensificati i controlli dei carabinieri, con l'impiego di unità speciali e mezzi blindati per contrastare lo spaccio di droga e i furti che affliggono la zona. L'operazione arriva dopo episodi di criminalità, tra cui l'esplosione di ordigni, che hanno spinto le forze dell'ordine a una risposta più decisa sul territorio. Lo riferisce Il Messaggero.",
