   "lead": "Al centro del Skift Data + AI Summit Europe 2026 si è discusso di come l'intelligenza artificiale sia ormai diffusa in tutto il settore turistico europeo, pur restando difficile da gestire pienamente. Di fronte a una regolamentazione più rigida e a un mercato dei viaggi frammentato, i dirigenti responsabili dell'AI nelle operazioni turistiche europee si trovano a dover affrontare conversazioni sempre più complesse e articolate sul tema. Lo riferisce Skift.",
