   "lead": "Il ministro della Salute egiziano Khaled Abdel Ghaffar ha discusso con l'omologo indonesiano Budi Sadikin delle modalità per sfruttare l'esperienza dell'Indonesia nel finanziamento di progetti sanitari e negli acquisti centralizzati di apparecchiature mediche. I due Paesi hanno esplorato una cooperazione più ampia su infrastrutture ospedaliere, tecnologia medica, oncologia e formazione del personale. L'incontro si è svolto presso la sede del ministero della Salute egiziano. Lo riferisce Daily News Egypt.",
