   "lead": "L'8 ottobre è uscito nelle sale russe 'Bitva motorov' ('Battaglia dei motori'), film del regista Ilya Malanin con Yura Borisov e Ivan Yankovsky, che racconta la squadra russa che partecipò al Rally di Monte Carlo del 1912 a bordo di un'auto Russo-Balt, senza parabrezza. Il dramma storico si ispira a eventi reali pur prendendosi diverse libertà artistiche, come chiariscono gli autori. Lo riferisce Meduza.",
