   "titolo": "Il fumo può danneggiare la fertilità di uomini e donne, secondo uno studio",
   "orig": "Smoking may affect fertility in both men and women",
   "lead": "Una nuova ricerca ha indagato come l'esposizione al fumo di sigaretta possa influire sulla salute riproduttiva sia maschile sia femminile. Lo studio ha individuato alterazioni nei processi biologici legati alla funzione ovarica nelle donne e alla produzione di spermatozoi negli uomini, fornendo nuovi elementi sugli effetti del tabagismo sulla capacità di procreare. La ricerca si inserisce nel filone di studi che esplorano le conseguenze del fumo sulla salute oltre ai già noti rischi cardiovascolari e oncologici. Lo riferisce Medical Xpress.",
   "more": [
    "La fertilità dipende da processi biologici complessi, tra cui la qualità degli ovociti nelle donne e la produzione di spermatozoi negli uomini: numerosi studi hanno già collegato stili di vita e sostanze tossiche, come il fumo, a un possibile impatto negativo su questi meccanismi."
   ],
