   "titolo": "Un robot cingolato cinese estrae ferro dalle sabbie del deserto del Taklamakan",
   "orig": "China’s Dune-like sand crawler could turn the whole Taklamakan Desert into an iron mine",
   "lead": "Ricercatori cinesi hanno costruito un robot cingolato semovente capace di estrarre ferro dalla sabbia, testandolo nelle dune del vasto deserto del Taklamakan, un'area grande quanto la Germania nella regione autonoma dello Xinjiang Uygur, nel nordovest della Cina. Il dispositivo richiama alla mente le mobili fabbriche descritte da Frank Herbert nel romanzo di fantascienza «Dune», che nel libro attraversano le sabbie del pianeta immaginario Arrakis per estrarre la preziosa sostanza chiamata melange o «spezia». Nella realtà, il macchinario percorre il deserto estraendo materiale ferroso di valore. Lo riferisce il South China Morning Post.",
   "more": [
    "Il deserto del Taklamakan è una delle aree desertiche più estese e inospitali dell'Asia centrale, situata nello Xinjiang; i suoi terreni sabbiosi ne hanno sempre reso difficile lo sfruttamento, rendendo significativa l'applicazione di tecnologie robotiche per l'estrazione mineraria."
   ],
