   "id": "zde135b87",
   "sez": "prima",
   "titolo": "Casa Bianca, primo breve briefing della nuova portavoce Katie Zacharia",
   "orig": "Inside Katie Zacharia's very brief White House briefing",
   "lead": "Katie Zacharia, avvocata californiana di 42 anni succeduta a Karoline Leavitt come portavoce della Casa Bianca, ha tenuto il suo primo incontro con la stampa: pochi minuti, appena tre domande accettate, e la ribadita fedeltà a Donald Trump. Nel corso del breve briefing Zacharia ha anche annunciato le dimissioni richieste a Kimberly Guilfoyle. La nuova portavoce è finita al centro delle polemiche per alcuni vecchi post di stampo cospirazionista legati a QAnon, rivolti tra gli altri contro Michelle Obama e Hillary Clinton.",
   "more": [
    "Karoline Leavitt era diventata portavoce della Casa Bianca nel gennaio 2025, all'inizio del secondo mandato di Trump, ed era stata la più giovane a ricoprire l'incarico."
   ],
