   "id": "z1ba39fe2",
   "sez": "italia",
   "titolo": "Meloni: «Tra Italia e Usa un'amicizia fondata su libertà e democrazia»",
   "orig": "Meloni: 'Tra l'Italia e gli Usa un'amicizia fondata su libertà e democrazia'",
   "lead": "Con un videomessaggio diffuso in occasione del lancio de «La Stampa Usa», edizione americana del quotidiano torinese, la presidente del Consiglio Giorgia Meloni ha ribadito la solidità del legame tra Roma e Washington, definendolo fondato su valori condivisi di libertà e democrazia. L'iniziativa editoriale punta a rafforzare l'informazione in lingua italiana per la comunità di origine italiana negli Stati Uniti. Lo riferisce ANSA.",
   "more": [
    "Meloni ha costruito gran parte della propria politica estera sul rapporto personale con l'amministrazione Trump, con cui il governo italiano mantiene una linea di stretto allineamento su diversi dossier internazionali."
   ],
