   "id": "z47823f98",
   "sez": "organizzazioni",
   "titolo": "Onu: a Taiz, in Yemen, assedio Houthi, colera e tagli agli aiuti mettono in pericolo i civili",
   "orig": "Yemen: Houthi siege, cholera outbreak and aid cuts put civilians in the crosshairs",
   "lead": "Le Nazioni Unite hanno lanciato un nuovo allarme sulla città yemenita di Taiz, nel sud-ovest del Paese, dove un assedio imposto dai ribelli Houthi sta facendo impennare i prezzi del cibo e provocando carenza di beni essenziali. A peggiorare la crisi umanitaria, definita «devastante» da un portavoce dell'Onu, contribuiscono un'epidemia di colera e i tagli ai finanziamenti umanitari internazionali. Il Paese resta diviso tra le aree controllate dagli Houthi e quelle sotto il governo riconosciuto, sostenuto dalla coalizione a guida saudita.",
   "more": [
    "Il conflitto in Yemen, cominciato nel 2014 con la presa di Sanaa da parte degli Houthi, ha provocato una delle peggiori crisi umanitarie al mondo, con milioni di persone dipendenti dagli aiuti internazionali per sopravvivere."
   ],
