   "titolo": "Manovra, slittano i tempi: tensione nella maggioranza sul taglio dell'Irpef",
   "orig": "Slittano i tempi della manovra. Tensione sul taglio dell'Irpef",
   "lead": "La legge di bilancio non è arrivata martedì sul tavolo del Consiglio dei ministri: Palazzo Chigi ha parlato di un errore materiale nell'ordine del giorno, ma restano le tensioni nella maggioranza sul taglio dell'Irpef al ceto medio, rivendicato dal vicepremier Antonio Tajani. Il testo della manovra è ora atteso in Parlamento a novembre, dopo l'invio a Bruxelles del Documento programmatico di bilancio entro il 15 ottobre. Lo riferisce ANSA.",
   "more": [
    "Il governo è nella fase conclusiva della preparazione della legge di bilancio 2027, che dovrà bilanciare le richieste di riduzione fiscale con i vincoli di finanza pubblica imposti dalle nuove regole europee."
   ],
