   "sez": "economia",
   "titolo": "Shell vende il business del gas domestico in Nigeria a Vaaris Energy",
   "orig": "Shell to sell Nigeria’s domestic gas business to Vaaris Energy",
   "lead": "La compagnia petrolifera Shell ha annunciato la cessione delle proprie attività nel mercato del gas domestico nigeriano a Vaaris Energy. L'operazione rientra nella strategia del gruppo britannico di semplificare il proprio portafoglio e concentrare gli investimenti sui settori in cui detiene un vantaggio competitivo, proseguendo il graduale ridimensionamento della propria presenza diretta nel delta del Niger. Lo riferisce Premium Times.",
   "more": [
    "Negli ultimi anni le grandi compagnie petrolifere occidentali hanno progressivamente ceduto attività onshore in Nigeria a operatori locali, a causa dei rischi di sicurezza e delle controversie legate all'inquinamento nel delta del Niger."
   ],
