   "titolo": "Riad, contratti da 1,47 miliardi di dollari a Siemens e Alstom per 94 nuovi treni della metropolitana",
   "orig": "RCRC Awards US$1.47 Billion Contracts To Siemens And Alstom For 94 New Riyadh Metro Trains",
   "lead": "L'ente saudita che gestisce i trasporti della capitale ha assegnato contratti per 1,47 miliardi di dollari a Siemens e Alstom per la fornitura di 94 nuovi treni destinati alla metropolitana di Riad. I nuovi convogli porteranno la flotta complessiva da 183 a 277 treni, aumentando la capacità della rete di circa il 60%. Lo riferisce Construction Business News Middle East.",
   "more": [
    "La metropolitana di Riad, una delle più estese reti di trasporto di massa costruite ex novo al mondo, è un elemento centrale del piano di modernizzazione urbana dell'Arabia Saudita nell'ambito del programma Vision 2030."
   ],
