   "lead": "La società di ingegneria Amey è stata nominata da Network Rail come «system integrator» per i sei progetti che compongono la prima fase della Northern Powerhouse Rail, la nuova linea ferroviaria ad alta capacità pensata per collegare le principali città del nord dell'Inghilterra. Lo riferisce New Civil Engineer.",
