   "titolo": "Oceano Indiano, la Francia ferma una petroliera sospettata di appartenere alla «flotta fantasma» russa",
   "orig": "OCÉAN INDIEN – La France arraisonne un pétrolier suspecté d'appartenir à la « flotte fantôme », Moscou dénonce une « violation flagrante » du droit international",
   "lead": "La Marina francese ha fermato lunedì la petroliera DF Peak, battente bandiera del Benin, a oltre 450 miglia nautiche a sud dell'isola di Réunion, nell'Oceano Indiano. La nave è sospettata di appartenere alla cosiddetta «flotta fantasma» usata dalla Russia per aggirare le sanzioni occidentali e di trasportare illegalmente carburante; è ora oggetto di un'inchiesta giudiziaria. Mosca ha definito l'operazione una «violazione flagrante» del diritto internazionale. Lo riferisce 2424.mg.",
   "more": [
    "La «flotta fantasma» è l'insieme di petroliere, spesso vecchie e battenti bandiere di comodo, usate per trasportare petrolio ed energia russi aggirando le sanzioni internazionali imposte dopo l'invasione dell'Ucraina; i fermi di queste navi da parte di Paesi europei si sono moltiplicati nell'ultimo anno."
   ],
