   "titolo": "Un nuovo trattamento per l'artrosi al ginocchio dà sollievo duraturo senza chirurgia",
   "orig": "New knee arthritis treatment delivers lasting pain relief without surgery",
   "lead": "Un nuovo trattamento sperimentale per l'artrosi al ginocchio utilizza minuscole particelle dissolvibili per bloccare i vasi sanguigni anomali che alimentano l'infiammazione, riducendo dolore e gonfiore senza bisogno di un intervento di protesi. In uno studio su 194 pazienti, l'80% ha riportato un sollievo dal dolore clinicamente significativo, mantenuto per almeno dodici mesi. Lo riferisce ScienceDaily – Medicina.",
   "more": [
    "L'artrosi al ginocchio è una delle principali cause di dolore cronico e disabilità nella popolazione anziana; le nuove tecniche mininvasive puntano a offrire un'alternativa alla chirurgia protesica, spesso riservata ai casi più avanzati."
   ],
