   "sez": "salute",
   "titolo": "Norvegia, anticorpi anomali legati alla riparazione del DNA potrebbero spiegare i tumori infantili",
   "orig": "Abnormal antibodies that disrupt DNA repair could explain childhood cancer",
   "lead": "Un gruppo di scienziati norvegesi ha individuato un possibile nuovo meccanismo alla base dello sviluppo dei tumori infantili: alcuni bambini produrrebbero una quantità anomala di anticorpi difettosi diretti contro i componenti del macchinario di riparazione del DNA, un insieme di centinaia di proteine che individuano e correggono i danni al genoma. Lo riferisce Medical Xpress.",
   "more": [
    "La comprensione dei meccanismi molecolari alla base dei tumori pediatrici, più rari ma spesso più aggressivi di quelli degli adulti, resta uno dei principali campi di ricerca dell'oncologia contemporanea."
   ],
