   "id": "z3d02305d",
   "sez": "salute",
   "titolo": "Anche il fratello maggiore di Papa Leone XIV ha un cancro, in cura sperimentale in Florida",
   "orig": "Hermano del papa León XIV también padece cáncer",
   "lead": "Louis Prevost, fratello maggiore di Papa Leone XIV, è anch'egli malato di cancro e riceve attualmente cure nell'ambito di una sperimentazione clinica in Florida, dopo che la malattia si è ripresentata tre mesi fa. Lo ha confermato la moglie Deborah Prevost alla rete americana Cbs News, poche ore dopo l'annuncio vaticano della diagnosi di adenocarcinoma polmonare del pontefice. Secondo quanto riferito, Louis Prevost era stato diagnosticato con un mieloma multiplo nel 2017 e aveva ricevuto nel 2019 un trattamento con cellule staminali che aveva tenuto la malattia sotto controllo per diversi anni. Lo riferisce Diario Libre.",
   "more": [
    "La coincidenza delle due diagnosi nella stessa famiglia, resa nota a poche ore di distanza, ha alimentato l'attenzione internazionale già altissima sulle condizioni di salute di Papa Leone XIV dopo l'intervento al Gemelli."
   ],
