   "orig": "Stop making sense: focus on sounds to help learn a language, study suggests",
   "lead": "Uno studio sull'apprendimento delle lingue straniere suggerisce che i cervelli delle persone più brave a imparare un nuovo idioma processano i suoni sconosciuti quasi come rumori, non come parole con un significato. Per questo, secondo i ricercatori, chi vuole imparare bene francese, arabo o ungherese farebbe meglio a concentrarsi all'inizio sui suoni della lingua, invece di partire subito da vocabolario e grammatica mandati a memoria. Lo riferisce The Guardian – Istruzione.",
