   "titolo": "Mondiale di rugby league al via: apre Australia-Nuova Zelanda, debutta anche il Libano a Port Moresby",
   "orig": "Less can be more for Rugby League World Cup",
   "lead": "Prende il via il Mondiale di rugby league, con la gara d'apertura tra Australia e Nuova Zelanda ad attirare l'attenzione di un torneo spesso criticato ma che quest'anno punta su un formato più snello. In Papua Nuova Guinea, intanto, la nazionale del Libano è atterrata a Port Moresby per il proprio debutto contro i padroni di casa Kumuls, allo stadio Santos National Football: per molti giocatori libanesi si tratta della prima visita nel Paese oceanico.",
   "more": [
    "Il rugby league, molto popolare in Australia, Nuova Zelanda e nel Pacifico, sta cercando negli ultimi anni di allargare la propria base internazionale, coinvolgendo anche federazioni minori come quella libanese, erede della diaspora libanese in Oceania."
   ],
