   "sez": "sport",
   "titolo": "Il Gran Premio di F1 in Malesia ha generato quasi 232 milioni di dollari",
   "orig": "F1 race at Malaysia’s Sepang generated nearly US$232 million: Sports ministry",
   "lead": "Il Gran Premio del Bahrein di Formula 1, trasferito in via eccezionale sul circuito malese di Sepang, ha generato un impatto economico di quasi 232 milioni di dollari, secondo il ministero dello Sport della Malesia. La gara, seguita da 827 milioni di spettatori nel mondo, ha confermato l'attrattiva internazionale della Formula 1 anche al di fuori delle sedi tradizionali del calendario. Lo riferisce CNA.",
   "more": [
    "Gli organizzatori sportivi di tutto il mondo guardano con crescente interesse alla Formula 1 come volano economico e turistico, al punto che diversi Paesi si contendono l'ospitalità di gare trasferite per motivi logistici o politici."
   ],
