   "id": "z9761e178",
   "sez": "mondo",
   "titolo": "Russia, nuovo attacco alle infrastrutture energetiche di Kiev senza preavviso agli alleati",
   "orig": "EN DIRECT, guerre en Ukraine : plusieurs régions frappées par des missiles russes, des infrastructures énergétiques endommagées à Kiev",
   "lead": "Un massiccio attacco russo con missili balistici ha colpito le infrastrutture energetiche di Kiev e della sua regione, causando alcuni decessi nella capitale e altri a Dnipropetrovsk e nella regione di Zaporizhzhia, secondo le autorità locali. Il presidente Volodymyr Zelensky ha denunciato che, per la seconda notte consecutiva, l'Ucraina non ha ricevuto alcun preavviso dagli alleati occidentali sull'attacco in arrivo, nonostante Kiev dipenda in larga parte dall'intelligence militare occidentale, in particolare statunitense, per individuare per tempo i raid russi.",
   "more": [
    "Dall'invasione russa del febbraio 2022, la rete energetica ucraina è uno dei bersagli principali degli attacchi di Mosca, soprattutto con l'avvicinarsi dell'inverno; le accuse di Kiev su un presunto rallentamento della condivisione di informazioni da parte degli alleati, in particolare degli Stati Uniti, si inseriscono in un contesto di trattative in corso su un possibile piano di pace."
   ],
