   "titolo": "Secondo il Washington Post, Usa ed Europa lavorano a un nuovo piano di pace per Ucraina e Russia",
   "orig": "The Washington Post: U.S. and Europe are developing a new plan to end the Russia–Ukraine war, offering incentives and security arrangements in exchange for a ceasefire along the current front line",
   "lead": "Secondo quanto riferito dal columnist David Ignatius sul Washington Post, Stati Uniti ed Europa starebbero elaborando insieme una nuova proposta per porre fine alla guerra tra Russia e Ucraina, basata su incentivi economici e garanzie di sicurezza reciproche per Kiev e Mosca, in cambio di un cessate il fuoco lungo l'attuale linea del fronte. Non è ancora chiaro se il piano verrà formalmente presentato alle due parti né quale accoglienza potrebbe ricevere. Lo riferisce Meduza.",
   "more": [
    "Dal ritorno alla Casa Bianca, Donald Trump ha più volte alternato aperture e pressioni su Mosca per chiudere il conflitto, dal vertice di Anchorage con Vladimir Putin ai successivi piani di pace, finora senza un cessate il fuoco stabile; europei e ucraini hanno più volte espresso cautela verso iniziative percepite come troppo favorevoli alle richieste russe."
   ],
