   "titolo": "Isola di Wight, un fossile rivela un predatore enigmatico vissuto 120 milioni di anni fa",
   "orig": "Isle of Wight fossil sheds light on enigmatic meat-eating dinosaurs",
   "lead": "Il cranio parziale di un predatore grande quanto una tigre, vissuto circa 120 milioni di anni fa sulle coste meridionali di quella che oggi è l'Isola di Wight, in Inghilterra, sta offrendo ai paleontologi nuovi elementi per comprendere un gruppo enigmatico di dinosauri carnivori, noti per inseguire le prede e dilaniarle con grandi artigli. Lo riferisce Daily Maverick.",
   "more": [
    "L'Isola di Wight, nel sud dell'Inghilterra, è uno dei siti paleontologici più ricchi d'Europa per i resti di dinosauri del primo Cretaceo, grazie alla particolare conformazione geologica delle sue scogliere costiere."
   ],
